    thread_local! {
        static CACHED: Rc<DwellThreshold> = {
            Rc::new(DwellThreshold {
    period: observation_heartbeat_period(),
    basis: "one heartbeat period — the log's existing clock. Law 2 requires that no subject stay quiet past T without a line naming it, and the heartbeat is already the cadence at which the log speaks, so T is DERIVED from the emitter's own period rather than picked. Escalation at 2T and 4T rides the same clock, which is why depth is a division and not a table of tuned constants.".to_string(),
})
        };
    }
    CACHED.with(|c: &Rc<DwellThreshold>| c.clone())
