pub fn observation_escalation_depth(quiet: Millisecond, t: Rc<DwellThreshold>) -> Nat {
    v1_rt::int_div(crate::std_measure::millisecond_count(quiet), crate::std_measure::millisecond_count(t.period.clone()))
}

pub fn observation_escalation_reveal_depth(quiet_subject: Rc<ObservationSubject>, quiet: Millisecond, t: Rc<DwellThreshold>) -> Nat {
    v1_rt::int_add((quiet_subject.segments.clone().len() as i64), observation_escalation_depth(quiet, t))
}

pub fn observation_escalation_subject(quiet_subject: Rc<ObservationSubject>, active_leaf: Rc<ObservationSubject>, quiet: Millisecond, t: Rc<DwellThreshold>) -> Rc<ObservationSubject> {
    if observation_subject_contains(quiet_subject.clone(), active_leaf.clone()) {
        Rc::new(ObservationSubject {
    segments: Rc::new(v1_rt::list_take(&active_leaf.segments.clone(), observation_escalation_reveal_depth(quiet_subject.clone(), quiet, t))),
})
    } else {
        quiet_subject.clone()
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum WatchdogVerdict {
    WatchdogQuiet,
    WatchdogOrphanedBegin {
        subject: Rc<ObservationSubject>,
        elapsed: Millisecond,
        budget: Millisecond,
    },
}
impl WatchdogVerdict {
    pub fn subject(&self) -> Rc<ObservationSubject> {
        match self {
            WatchdogVerdict::WatchdogQuiet => panic!("no subject on unit variant"),
            WatchdogVerdict::WatchdogOrphanedBegin { subject: __val, .. } => __val.clone(),
        }
    }
    pub fn elapsed(&self) -> Millisecond {
        match self {
            WatchdogVerdict::WatchdogQuiet => panic!("no elapsed on unit variant"),
            WatchdogVerdict::WatchdogOrphanedBegin { elapsed: __val, .. } => __val.clone(),
        }
    }
    pub fn budget(&self) -> Millisecond {
        match self {
            WatchdogVerdict::WatchdogQuiet => panic!("no budget on unit variant"),
            WatchdogVerdict::WatchdogOrphanedBegin { budget: __val, .. } => __val.clone(),
        }
    }
}

pub fn observation_watchdog(subject: Rc<ObservationSubject>, elapsed: Millisecond, budget: Millisecond) -> Rc<WatchdogVerdict> {
    match (*crate::std_temporal_effect::stall_budget_verdict(Rc::new(EffectStallBudget {
    step_id: observation_subject_render(subject.clone()),
    limit_ms: budget.clone(),
    elapsed_ms: elapsed.clone(),
}))).clone() {
    StallBudgetVerdict::StallWithinBudget => Rc::new(WatchdogVerdict::WatchdogQuiet),
    StallBudgetVerdict::StallBudgetExceeded { elapsed_ms: e, limit_ms: l, .. } => Rc::new(WatchdogVerdict::WatchdogOrphanedBegin {
    subject: subject.clone(),
    elapsed: e.clone(),
    budget: l.clone(),
}),
}
}

pub fn observation_subject_render(subject: Rc<ObservationSubject>) -> String {
    match observation_subject_path(subject).join(&" ".to_string()) {
    ref __s if __s == "" => "run=unattributed".to_string(),
    rendered => rendered.clone(),
}
}

pub fn observation_watchdog_attention(v: Rc<WatchdogVerdict>) -> AttentionLevel {
    match (*v.clone()).clone() {
    WatchdogVerdict::WatchdogQuiet => AttentionLevel::Ambient,
    WatchdogVerdict::WatchdogOrphanedBegin { .. } => AttentionLevel::Anomaly,
}
}

