pub fn observation_rollup_accept(rollup: Rc<ObservationRollup>, event: Rc<ObservationEvent>) -> Rc<ObservationRollupAccept> {
    if observation_subject_contains(rollup.subject.clone(), event.subject.clone()) {
        Rc::new(ObservationRollupAccept::RollupAccepted {
    rollup: Rc::new(ObservationRollup {
    subject: rollup.subject.clone(),
    counts: observation_counts_accept(rollup.counts.clone(), observation_event_class(event.clone())),
    active_leaf: Some(event.subject.clone()),
    elapsed: observation_rollup_add_elapsed(rollup.elapsed.clone(), observation_wall(event.clone())),
    peak_rss: observation_rollup_max_rss(rollup.peak_rss.clone(), event.rss.clone()),
    measurement_absent: v1_rt::int_add(rollup.measurement_absent.clone(), observation_measurement_absent_delta(observation_wall(event.clone()))),
}),
})
    } else {
        Rc::new(ObservationRollupAccept::RollupSubjectOutOfScope {
    subject: event.subject.clone(),
})
    }
}

pub fn observation_rollup_contract() -> Rc<Disposition> {
    thread_local! {
        static CACHED: Rc<Disposition> = {
            Rc::new(Disposition::Terminal {
    reason: "The rollup fold is a pure reader over the vocabulary this module already owns — subject containment (observation_subject_contains, itself std.algebra is_prefix_of), grain depth, and the single density table. It mints no grain taxonomy, no second collapse rule and no threshold: which grain to roll up to is the consumer's parameter, and when to emit is the renderer's projection over these counts. Terminal because the fold is total over the closed event-class roster; a new class must extend observation_counts_accept, which the exhaustive match forces.".to_string(),
})
        };
    }
    CACHED.with(|c: &Rc<Disposition>| c.clone())
}

