        match (*scope.clone()).clone() {
    LedgerReadScope::SingleProducerRead { producer: prod, .. } => Rc::new(ParentResolution::ParentOutsideReadScope {
    scope: prod.clone(),
    parent_id: p.id.clone(),
}),
    LedgerReadScope::AttemptUnionRead => Rc::new(ParentResolution::ParentMissingFromAttempt {
    parent_id: p.id.clone(),
}),
}
